$string['modelregistry:field_eol_date_help'] = 'घोषित बन्दी वा बन्द हुने मिति, YYYY-MM-DD ढाँचामा। कुनै जीवन-अन्त्य घोषणा नभएको बेला खाली छोड्नुहोस् — खाली भनेको अघोषित हो, सुरक्षित होइन। यसलाई तपाईंको आफ्नो समय क्षेत्रमा होइन, UTC को पात्रो दिनका रूपमा पढिन्छ, ताकि यो पङ्क्ति पढ्ने सबैले एउटै हप्ताको योजना बनाऊन्।';
$string['modelregistry:field_eol_surface'] = 'जीवन-अन्त्य लागू हुने सतह';
$string['modelregistry:field_eol_surface_help'] = 'मिति कुन API सतहका लागि घोषित थियो: <code>gemini-developer-api</code>, <code>vertex-ai</code>, <code>openai-api</code>, <code>azure-openai</code>, <code>bedrock</code>, वा हरेक सतहका लागि <code>any</code>। मिति प्रविष्ट गर्दा यो अनिवार्य छ, र यो कागजी झन्झट होइन: gemini-2.5-flash 2026-10-16 मा बन्द हुने भनी रिपोर्ट गरिएको थियो, तर त्यो Vertex AI को जीवनचक्र घटना थियो, यो साइटले कल गर्ने Gemini Developer API को होइन। सतह बिना, त्यो मितिले कतै नजाने मोडेलका बारेमा उत्पादन-आउटेजको चेतावनी बजाउँछ। यो साइटले वास्तवमा कल गर्ने सतहहरू मूल्य ड्रिफ्ट अन्तर्गत सूचीबद्ध गर्नुहोस् ताकि तपाईंका नभएका सतहहरू जानकारीमूलक मात्र रहून्।';
